# The pipeline-order section is guidance, not additional selectable rules.
known={('Cleaning','Trim leading and trailing spaces'):'trim',('Cleaning','Lowercase normalization'):'lowercase',('Cleaning','Uppercase normalization'):'uppercase',('Transformation','ISO 8601 date standardization'):'date',('Validation','NOT NULL'):'required',('Validation','Required value'):'required',('Validation','UNIQUE'):'unique',('Validation','Min/max range'):'range'}
seen=set();entries=[]
for item in catalog:
 pair=(item['category'],item['name'])
 if pair in seen:continue
 seen.add(pair);item['operation']=known.get(pair,'reference')
 item['id']='REF-'+re.sub(r'[^a-z0-9]+','-',(item['category']+'-'+item['name']).lower()).strip('-')
 if item['operation']=='date':item['defaults']['dateFormat']='%d/%m/%Y'
 assert len(item['example'].split())<10,item
 entries.append(item)
Path('work/reference_catalog.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'rules':len(entries),'categories':{c:sum(r['category']==c for r in entries) for c in ['Cleaning','Transformation','Validation']}}))
